content.text:
请对以下 case 进行三维加权评分。

=== case_id ===
Case-15-smart-home-009

=== 用户原始指令 (query.txt) ===
弄个窗帘控制卡吧，点一下跳到APP，日程能看到，状态标出来

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "弄个窗帘控制卡吧，点一下跳到APP，日程能看到，状态标出来",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.hmos.settings",
        "abilityName": "com.huawei.hmos.settings.MainAbility",
        "uri": "intelligent_scene_entry"
      }
    }
  ],
  "dataModelSchema": {
    "device": {
      "name": {
        "type": "string",
        "description": "窗帘设备名称",
        "sampleValue": "客厅窗帘"
      },
      "statusText": {
        "type": "string",
        "description": "窗帘当前状态确认文本",
        "sampleValue": "已确认 · 打开"
      },
      "openPercent": {
        "type": "number",
        "description": "窗帘当前开合百分比数值",
        "sampleValue": 68
      },
      "openPercentText": {
        "type": "string",
        "description": "窗帘当前开合百分比展示文本",
        "sampleValue": "68%"
      },
      "modeText": {
        "type": "string",
        "description": "窗帘当前控制模式或执行说明",
        "sampleValue": "日程自动"
      }
    },
    "data": {
      "calendar": {
        "items": [
          {
            "entityId": {
              "type": "string",
              "description": "日程唯一标识符",
              "sampleValue": "curtain_schedule_001"
            },
            "title": {
              "type": "string",
              "description": "日程标题",
              "sampleValue": "早晨自动开启"
            },
            "dtStart": {
              "type": "string",
              "description": "日程开始时间",
              "sampleValue": "07:30"
            },
            "dtEnd": {
              "type": "string",
              "description": "日程结束时间",
              "sampleValue": "07:45"
            },
            "eventLocation": {
              "type": "string",
              "description": "日程关联位置或设备区域",
              "sampleValue": "客厅"
            }
          }
        ]
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/house_fill.svg",
      "description": "房屋实心图标，黑白双色，适合表示智能家居入口或家庭设备对象。"
    },
    {
      "src": "resources/base/media/calendar_fill.svg",
      "description": "日历实心图标，黑色，适合表示日程管理、日历事件查看和当日安排。"
    }
  ]
}

